import React, { useState } from 'react';
import InputForm from './components/InputForm';
import ResultsTable from './components/ResultsTable';
import RegexUploader from './components/RegexUploader';
import './styles/App.css';

const App: React.FC = () => {
    const [inputTitle, setInputTitle] = useState<string>('');
    const [validationResults, setValidationResults] = useState<any[]>([]);
    const [regexDefinitions, setRegexDefinitions] = useState<any[]>([]);

    const handleInputChange = (title: string) => {
        setInputTitle(title);
    };

    const handleValidationResults = (results: any[]) => {
        setValidationResults(results);
    };

    const handleRegexUpload = (regexes: any[]) => {
        setRegexDefinitions(regexes);
    };

    return (
        <div className="app-container">
            <h1>TagGen</h1>
            <RegexUploader onRegexUpload={handleRegexUpload} />
            <InputForm inputTitle={inputTitle} onInputChange={handleInputChange} onValidate={handleValidationResults} regexDefinitions={regexDefinitions} />
            <ResultsTable results={validationResults} />
        </div>
    );
};

export default App;
